int pair_sum(const int a[], int n, int target, int *i, int *j) {
  int l = 0, r = n - 1;
  while (l < r) {
    int s = a[l] + a[r];
    if (s == target) { *i = l; *j = r; return 1; }
    if (s < target) l++; else r--;
  }
  return 0;
}

int dedupe(int a[], int n) {
  if (!n) return 0;
  int w = 1;
  for (int r = 1; r < n; r++)
    if (a[r] != a[w - 1]) a[w++] = a[r];
  return w;
}

/* longest substring without repeating characters */
int seen[256] = {0}, best = 0;
for (int l = 0, r = 0; s[r]; r++) {
  seen[(unsigned char)s[r]]++;
  while (seen[(unsigned char)s[r]] > 1) seen[(unsigned char)s[l++]]--;
  if (r - l + 1 > best) best = r - l + 1;
}
